use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use findamodel::geometry::support_reader;
use findamodel::geometry::{Triangle, Vec3};
use rayon::prelude::*;
use serde_json::{Value, json};

/// The synthetic scenes' raft height.
const RAFT_MM: f32 = 3.0;

fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("support_synthetic")
}

fn variant_ids() -> Vec<String> {
    std::fs::read_to_string(dir().join("variants.txt"))
        .expect("variants.txt")
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .map(String::from)
        .collect()
}

/// (case, sides, rotation, style) of a variant id such as `b01_bend25__n12_r0_sep`.
fn parse(id: &str) -> (String, usize, i64, String) {
    let (case, rest) = id.split_once("__").expect("a variant id");
    let parts: Vec<&str> = rest.split('_').collect();
    (
        case.to_string(),
        parts[0][1..].parse().expect("sides"),
        parts[1][1..].parse().expect("rotation"),
        parts[2].to_string(),
    )
}

fn to_f32(t: &[[f64; 3]; 3]) -> [[f32; 3]; 3] {
    t.map(|p| p.map(|x| x as f32))
}

fn triangles(t: &[[[f32; 3]; 3]]) -> Vec<Triangle> {
    let v = |p: [f32; 3]| Vec3::new(p[0], p[1], p[2]);
    t.iter().map(|t| Triangle::new(v(t[0]), v(t[1]), v(t[2]), Vec3::new(0.0, 0.0, 1.0))).collect()
}

/// One variant's results.
struct Outcome {
    stages: Value,
    dump: Option<Value>,
}

fn run(id: &str, keep: bool) -> Outcome {
    let (case, sides, rot, style) = parse(id);
    let g = match cases::generate(&case, sides, rot, &style) {
        Ok(g) => g,
        Err(e) => return Outcome { stages: json!({"error": e}), dump: None },
    };
    // As the prototype read them: from STL files, in f32.
    let model32: Vec<[[f32; 3]; 3]> = g.model.iter().map(to_f32).collect();
    let support32: Vec<[[f32; 3]; 3]> = g.support.iter().map(to_f32).collect();
    let mut truth = g.truth.clone();
    let m = measure::measure(&model32, &support32, &g.samples);
    let v = score::validate(&mut truth, &m.isect, &m.touch, &m.dist);
    let r = support_reader::read(&triangles(&model32), &triangles(&support32), RAFT_MM);
    let rd = reading::reading(&r.classification);
    let lay = reading::layout(&r.classification);
    let s1 = score::stage1(&truth, &rd);
    let s2 = score::stage2(&truth, &lay);
    let nm = nominal::build(&lay);
    let model64: Vec<[[f64; 3]; 3]> = model32.iter().map(measure::widen).collect();
    let sup: Vec<[[f64; 3]; 3]> = nm.tris.iter().map(|t| t.map(|p| p.0)).collect();
    let (isect, touch) = (measure::isect(&sup, &model64), measure::touch(&sup, &model64));
    let labels = |i: u32| nm.labels[i as usize].name().to_string();
    let s4 = score::stage4(&truth, &nm.tris, &isect, &touch, &labels, &v);
    let stages = json!({
        "validate": v.errors.is_empty(),
        "1 reader labels": s1["pass"],
        "2 layout": s2["pass"],
        "4a clips (nominal)": s4["clip_pass"],
        "4b loops (nominal)": s4["loop_pass"],
    });
    let dump = keep.then(|| {
        json!({
            "id": id, "title": truth["title"], "real": truth["real"], "notes": truth["notes"], "params": truth["params"],
            "stages": stages, "gen_errors": v.errors, "s1": s1, "s2": s2, "s4": s4,
            "check": r.classification.check, "exceptions": r.classification.exceptions,
            "model": model32, "support": support32, "nominal": nm.tris.iter().map(|t| t.map(|p| p.0.map(|x| x as f32))).collect::<Vec<_>>(),
            "truth": truth, "reading": rd, "layout": lay,
        })
    });
    Outcome { stages, dump }
}

/// Runs the variants and holds them to `expected.json`.
fn check(ids: &[String]) {
    let dump_dir = std::env::var("SYNTHETIC_DUMP").ok().map(PathBuf::from);
    if let Some(d) = &dump_dir {
        std::fs::create_dir_all(d).expect("dump dir");
    }
    let got: BTreeMap<String, Value> = ids
        .par_iter()
        .map(|id| {
            let o = run(id, dump_dir.is_some());
            if let (Some(d), Some(v)) = (&dump_dir, &o.dump) {
                std::fs::write(d.join(format!("{id}.json")), serde_json::to_vec(v).expect("json")).expect("dump");
            }
            (id.clone(), o.stages)
        })
        .collect();
    let path = dir().join("expected.json");
    let mut expected: BTreeMap<String, Value> =
        std::fs::read(&path).ok().and_then(|b| serde_json::from_slice(&b).ok()).unwrap_or_default();
    if std::env::var("SYNTHETIC_UPDATE").is_ok() {
        expected.extend(got.clone());
        std::fs::write(&path, serde_json::to_string_pretty(&expected).expect("json") + "\n").expect("expected.json");
        return;
    }
    let mut changed = Vec::new();
    for (id, stages) in &got {
        match expected.get(id) {
            Some(want) if want == stages => {}
            Some(want) => changed.push(format!("{id}: expected {want}, got {stages}")),
            None => changed.push(format!("{id}: not in expected.json (got {stages})")),
        }
    }
    let all = |k: &str| got.values().filter(|s| s[k] == true).count();
    eprintln!(
        "{} variants: validate {}, 1 reader labels {}, 2 layout {}, 4a clips {}, 4b loops {}",
        got.len(),
        all("validate"),
        all("1 reader labels"),
        all("2 layout"),
        all("4a clips (nominal)"),
        all("4b loops (nominal)")
    );
    assert!(changed.is_empty(), "{} variants changed:\n{}", changed.len(), changed.join("\n"));
}

/// The base variant of every case (8 sides, no rotation, separate shells; the first variant
/// where a case has no 8-sided one).
#[test]
fn every_synthetic_case_reads_as_before() {
    let ids = variant_ids();
    let mut base: BTreeMap<String, String> = BTreeMap::new();
    for id in &ids {
        let case = parse(id).0;
        let e = base.entry(case).or_insert_with(|| id.clone());
        if id.ends_with("__n8_r0_sep") {
            *e = id.clone();
        }
    }
    check(&base.into_values().collect::<Vec<_>>());
}

/// Every variant (side counts 8, 12, 16 and 32, rotations, joined and welded shells).
#[test]
fn every_synthetic_variant_reads_as_before() {
    check(&variant_ids());
}

/// The generator still makes every case in the list (a case that stops generating fails here).
#[test]
fn the_generator_makes_every_listed_case() {
    let known: std::collections::BTreeSet<String> = cases::cases().iter().map(|c| c.id.to_string()).collect();
    for id in variant_ids() {
        assert!(known.contains(&parse(&id).0), "{id}");
    }
}

/// One read of a variant, as text: the whole classification and the layout the VOXL writer takes.
fn read_text(id: &str) -> String {
    let (case, sides, rot, style) = parse(id);
    let g = cases::generate(&case, sides, rot, &style).expect("the variant generates");
    let model32: Vec<[[f32; 3]; 3]> = g.model.iter().map(to_f32).collect();
    let support32: Vec<[[f32; 3]; 3]> = g.support.iter().map(to_f32).collect();
    let r = support_reader::read(&triangles(&model32), &triangles(&support32), RAFT_MM);
    format!("{}\n{:?}", serde_json::to_string(&r.classification).expect("json"), r.classification.layout)
}

/// Reads the variants in a thread pool of `threads`.
fn read_in_pool(ids: &[String], threads: usize) -> Vec<String> {
    let pool = rayon::ThreadPoolBuilder::new().num_threads(threads).build().expect("thread pool");
    pool.install(|| ids.iter().map(|id| read_text(id)).collect())
}

/// The reader gives the same reading on every run and on any number of threads, on the cases
/// where the prototype's tools were hash-order dependent (welded f03_two, n03_endin_nonman's
/// loops) or gave two answers (k03_modeltree).
#[test]
fn the_reader_is_deterministic_across_runs_and_thread_counts() {
    let ids: Vec<String> = [
        "f03_two__n16_r0_welded",
        "f03_two__n8_r0_welded",
        "n03_endin_nonman__n12_r0_sep",
        "n03_endin_nonman__n16_r30_sep",
        "k03_modeltree__n12_r0_sep",
        "k03_modeltree__n16_r0_joined",
    ]
    .map(String::from)
    .to_vec();
    let first = read_in_pool(&ids, 1);
    for threads in [1, 4, 40] {
        let again = read_in_pool(&ids, threads);
        for (k, id) in ids.iter().enumerate() {
            assert!(first[k] == again[k], "{id} reads differently on {threads} threads");
        }
    }
}

/// SYNTHETIC_DETERMINISM=<threads,...>: every variant's reading hashed in pools of those sizes
/// (a manual check; prints the variants whose reading differs).
#[test]
fn determinism_sweep() {
    let Ok(spec) = std::env::var("SYNTHETIC_DETERMINISM") else { return };
    use std::hash::{Hash, Hasher};
    let ids = variant_ids();
    let mut runs: Vec<(usize, Vec<u64>)> = Vec::new();
    for t in spec.split(',').map(|x| x.parse::<usize>().expect("threads")) {
        let pool = rayon::ThreadPoolBuilder::new().num_threads(t).build().expect("pool");
        let hs: Vec<u64> = pool.install(|| {
            ids.par_iter()
                .map(|id| {
                    let mut h = std::collections::hash_map::DefaultHasher::new();
                    read_text(id).hash(&mut h);
                    h.finish()
                })
                .collect()
        });
        runs.push((t, hs));
    }
    let mut bad = 0;
    for (k, id) in ids.iter().enumerate() {
        if runs.iter().any(|r| r.1[k] != runs[0].1[k]) {
            bad += 1;
            eprintln!("DIFF {id}");
        }
    }
    eprintln!("determinism sweep: {} variants, {bad} differ across {spec}", ids.len());
}
